**行号：L142–L202**

### 代码原文
```ts
142    //==========================================================
143    //M 按配置顺序发起挂载并限时等待
144    //==========================================================
145    for (const entry of entries) {
146      //M 先按配置名找内置插件，也为加载失败的状态记录注入声明。
147      const builtIn = pluginIndex.BUILT_IN[entry.name];
148      const row: resourcesModule.PluginStatus = {
149        name: entry.name,
150        state: 'mounting',
151        error: '',
152        inject: builtIn?.inject ?? [],
153      };
154      try {
155        let plugin = builtIn;
156        if (plugin === undefined) {
157          //M 内置表查不到才从外部插件文件夹加载入口。
158          const root = app.resources.root;
159          plugin = await loadExternalPlugin(entry.name, root);
160        }
161
162        //M 等待 Cordis apply。状态监听使用 thenable 后面的原 fiber。
163        row.inject = plugin.inject ?? [];
164        const mounted = app.plugin(plugin, entry.config);
165        const fiber = mounted.ctx.fiber;
166        starting.set(fiber, row);
167
168        //M 首次等待结束时也可能在等注入，记成等服务。异步失败即使发生在超时之后也照常记账。
169        const finished = fiber.await().then(() => {
170          if (fiber.state === cordis.FiberState.PENDING && row.error === '') {
171            row.state = 'waiting';
172          }
173          return true;
174        }, (error: unknown) => {
175          if (starting.delete(fiber)) {
176            recordPluginFailure(row, error);
177          }
178          return true;
179        });
180
181        const timer = new AbortController();
182        const options = { signal: timer.signal };
183        const deadline = timers.setTimeout(pluginMountTimeoutMs, false, options);
184        const waiting = [finished, deadline];
185        try {
186          const inTime = await Promise.race(waiting);
187          if (!inTime && starting.has(fiber)) {
188            //G 到点只结束本次等待，状态还是 mounting。保留 fiber，让它完成后还能发状态和服务通知。
189            const seconds = pluginMountTimeoutMs / 1000;
190            row.error = `启动超过 ${String(seconds)} 秒，先挂后面的，它继续在后台起`;
191            console.error(`插件 ${row.name} ${row.error}`);
192          }
193        } finally {
194          timer.abort();
195        }
196      } catch (error) {
197        recordPluginFailure(row, error);
198      }
199      //M 维持配置顺序，每次发起挂载只占一行，供 health 和启动流程读。
200      app.resources.pluginStatus.push(row);
201    }
202
```

### 解释
- L145 按配置顺序发起挂载。单个插件超过等待上限后继续在后台启动。
- L199–L201 每个插件在 `pluginStatus` 只占一行，按配置顺序供健康检查和教程读取。

